983	// absolute pins a configured file path to one meaning.
984	//
985	// A relative gitleaks_config does not mean the same thing on both sides of the
986	// Docker boundary — DevDesk's working directory in binary mode, the container's
987	// in Docker mode — and the file is now mounted, so the two readings would
988	// disagree about which file is scanned with. Resolving it here settles it
989	// against DevDesk's own working directory, once, at load: the path that gets
990	// mounted and the path the configuration view shows are then the same string.
991	//
992	// A path that cannot be resolved is left as it was rather than dropped:
993	// RunGitleaks refuses an unreadable config with the reason, and that is a
994	// better place to fail than a config file that silently loses a setting.
995	func absolute(path string) string {
996		if path == "" {
997			return ""
998		}
999		abs, err := filepath.Abs(path)
1000		if err != nil {
1001			return path
1002		}
1003		return abs
1004	}
