773	// normalizeProxyPort returns the port to serve on: the default for a file that
774	// does not say, and the default — loudly — for one that states a port the
775	// proxy cannot bind. Unlike the other network dials, a wrong value here is not
776	// merely a slow probe: it would make every named route unbindable.
777	func normalizeProxyPort(port int) int {
778		switch {
