174	// handleRegistryGroupDetected records a discovery. Nothing forwards it to the
175	// browser any more: the browser reads the cache when it opens, so a refresh is
176	// something the Registries tab does and the Members column reports.
177	//
178	// Three outcomes (DEVDESK-510): a listing, even an empty one, replaces the entry
179	// and clears any refusal; a refusal is held beside the listing, which it leaves
180	// alone; any other error changes nothing and says so in red. The instant is
181	// msg.At, the one the Cmd wrote to disk.
182	func (m Model) handleRegistryGroupDetected(msg RegistryGroupDetectedMsg) (tea.Model, tea.Cmd) {
183		delete(m.refreshingGroups, msg.Slug)
184	
185		var refused *registrymgr.MembersRefusedError
186		switch {
187		case msg.Err == nil:
188			return m.handleGroupListed(msg)
189		case errors.As(msg.Err, &refused):
190			return m.handleGroupRefused(msg.Slug, refused, msg.At)
191		}
192		log.Printf("INFO [oci_resources] group detection failed for %s: %v", oci.RedactRegistryURL(msg.RegistryURL), msg.Err)
193		// The cache keeps what was last known rather than being emptied by an
194		// unreachable manager, so the column keeps showing it — stale, and
195		// visibly so. A refusal held in memory stays too: it is still the last
196		// fact known about this group.
197		m.updateRegistryTable()
198		return m, m.footer.Error("Group refresh failed — check logs")
199	}
