204		if msg.Slug != "" {
205			m.groupCache[msg.Slug] = cache.RegistryGroupEntry{
206				Members:      toCachedMembers(msg.Members),
207				DiscoveredAt: msg.At,
208			}
209			delete(m.groupRefusals, msg.Slug)
210		}
211		m.updateRegistryTable()
212		return m, nil
