216	// listing last known stays as it is: a refusal says nothing about the members.
217	func (m Model) handleGroupRefused(slug string, e *registrymgr.MembersRefusedError, at time.Time) (tea.Model, tea.Cmd) {
218		r := refusalRecord(e, at)
219		if slug != "" {
