222			}
223			m.groupRefusals[slug] = r
224		}
225		log.Printf("INFO [oci_resources] group members refused (status %d, anonymous %t)", r.Status, r.Anonymous)
226		m.updateRegistryTable()
227		return m, m.footer.Warn(refusedFooterText(m.refusalView(slug, r)))
228	}
