230	// toCachedMembers converts what the detector returned into what the cache and
231	// the table hold.
232	func toCachedMembers(members []registrymgr.GroupMember) []cache.RegistryGroupMember {
233		out := make([]cache.RegistryGroupMember, 0, len(members))
234		for _, m := range members {
235			out = append(out, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix, Type: m.Type})
236		}
237		return out
238	}
