17	// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
18	func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
19		if len(m.registries) == 0 {
20			return m, m.footer.Warn("No registries configured — add one in the Registries tab")
21		}
22		// Config plus cache, read here and now: no network, no waiting, no state
23		// that ignores esc (D13).
24		// Reopening replaces a browser that may still have a lot in flight.
25		m.registryBrowser.cancelInFlight()
26		m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
27		m.registryBrowser.SetScanCache(m.scanCache)
28		m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
29		return m, nil
30	}
