32	// closeMultiRegistryBrowser drops the browser, remembering what the user
33	// unchecked so the next visit opens on the same selection.
34	func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
35		if m.registryBrowser == nil {
36			return m, nil
37		}
38		m.registryBrowser.cancelInFlight()
39		deselected := m.registryBrowser.Deselected()
40		m.registryBrowser = nil
41	
42		m.browserDeselected = make(map[string]bool, len(deselected))
43		for _, key := range deselected {
44			m.browserDeselected[key] = true
45		}
46		return m, saveBrowserSelectionCmd(deselected)
47	}
