170	}
171	
172	// Default reaches each image's own registry, with the credentials the engine
173	// holds for it or anonymously.
174	func Default() Registry {
175		creds := func(ref remediation.Ref) (string, string) {
176			host := ref.Registry
177			if host == "" {
178				host = "docker.io"
179			}
180			user, pass, _ := docker.GetStoredCreds(host)
181			return user, pass
182		}
183		return Registry{
184			Digest: func(ref remediation.Ref, tag string) (string, error) {
185				user, pass := creds(ref)
186				return oci.ManifestDigest(oci.RegistryAPIBase(ref.Registry), ref.Repository, tag, user, pass)
187			},
188			Tags: func(ref remediation.Ref) ([]string, error) {
189				user, pass := creds(ref)
190				return oci.ListRegistryTags(oci.RegistryAPIBase(ref.Registry), ref.Repository, user, pass)
191			},
192		}
193	}
